// Let's uncheck Corolla Cross, Corolla Hatchback, Corolla iM, GR Corolla
const uncheckResult = await browserjs(tabId, () => {
  const container = document.getElementById('filter-panel-content-make-model');
  if (!container) return { success: false, reason: "no container" };
  const toUncheck = ['Corolla Cross', 'Corolla Hatchback', 'Corolla iM', 'GR Corolla'];
  const labels = Array.from(container.querySelectorAll('label'));
  const clicked = [];
  for (const label of labels) {
    for (const name of toUncheck) {
      if (label.innerText.startsWith(name)) {
        const input = label.querySelector('input');
        if (input && input.checked) {
          input.click();
          clicked.push(name);
        }
      }
    }
  }
  return { success: true, clicked };
});
