const tabId = 1962625065;
const results = await browserjs(tabId, () => {
  const articles = Array.from(document.querySelectorAll('article')).map(a => {
    const heading = a.querySelector('h2, h3')?.innerText;
    const trimAndMiles = a.querySelector('.km-indicator, [class*="trim"], [class*="mileage"]')?.innerText || a.innerText;
    const priceEl = a.innerText.match(/\$[0-9,]+/g);
    return {
      title: heading,
      rawText: a.innerText.split('\n').filter(t => t.trim().length > 0).slice(0, 8)
    };
  }).filter(a => a.title && a.title.includes('Toyota'));

  const countText = document.querySelector('[class*="matches"], [class*="count"], main')?.innerText.match(/([0-9,]+)\s*matches/i)?.[0];

  return {
    url: window.location.href,
    title: document.title,
    countText,
    totalCarArticles: articles.length,
    firstCars: articles.slice(0, 6)
  };
});
console.log(JSON.stringify(results, null, 2));

