const tabId = 1962625065;
const verifyData = await browserjs(tabId, () => {
  const h1 = document.querySelector('h1')?.innerText;
  const countMatch = document.body.innerText.match(/([0-9,]+)\s*matches/i)?.[0];
  const url = window.location.href;
  const filtersApplied = Array.from(document.querySelectorAll('[class*="chip"], [class*="tag"], [class*="selected"], [class*="Filter"]'))
    .map(el => el.innerText?.trim())
    .filter(t => t && (t.includes('Red') || t.includes('2018') || t.includes('Toyota') || t.includes('Corolla')));

  // Get first 10 cars with year, make, model, trim, price, miles
  const cars = Array.from(document.querySelectorAll('article')).map(art => {
    const title = art.querySelector('h2, h3')?.innerText;
    const text = art.innerText;
    return { title, text: text.split('\n').filter(Boolean).slice(0, 8) };
  }).filter(c => c.title && c.title.includes('Corolla'));

  return {
    h1,
    url,
    countMatch,
    cars: cars.slice(0, 5)
  };
});
console.log(JSON.stringify(verifyData, null, 2));

